-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (8142, 29, 'Orte der Begegnung, Nachbarschaftstreffs und Stadtteilzentren fördern (Land)', 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'gemischt', 'https://europepmc.org/article/MED/21843337', 'land', null, true, 'blind'),
  (8143, 29, 'Landesstrategie, Beauftragte und Koordination gegen Einsamkeit (Land)', 'Strategie und Koordination schaffen selbst kein Angebot; die Wirkung hängt von den Maßnahmen ab, die daraus folgen. Wirkung solcher Strukturen kaum untersucht, rechtlich und finanziell leicht umsetzbar.', 'offen', null, 'land', null, true, 'blind'),
  (8144, 29, 'Aufsuchende Hilfen, Besuchsdienste und organisierte Nachbarschaftshilfe (Land)', 'Erreicht auch Menschen, die nicht von sich aus Treffpunkte aufsuchen. Besuchsangebote wirkten in Übersichten seltener als Gruppenangebote (60 % gegenüber 79 % der Studien mit Verbesserung). Gut umsetzbar.', 'gemischt', 'https://europepmc.org/article/MED/21843337', 'land', null, true, 'blind'),
  (8145, 29, 'Vereine, Ehrenamt und Engagementstrukturen fördern (Land)', 'Vereine und Engagement bieten Kontaktgelegenheiten, die Förderung wirkt aber nur indirekt und erreicht Verwitwete nicht gezielt. Wirkung auf Einsamkeit kaum untersucht; leicht umsetzbar.', 'offen', null, 'land', null, true, 'blind'),
  (8146, 29, 'Vermittlung von Wohnpartnerschaften „Wohnen für Hilfe“ (Land)', 'Bietet Alltagskontakt im selben Haushalt, erreicht aber nur wenige Menschen und setzt passende Wohnungen voraus. Wirkung auf Einsamkeit kaum untersucht; Vermittlung ist schnell aufzubauen.', 'offen', null, 'land', null, true, 'blind'),
  (8147, 29, 'Gemeinschaftliche und generationenübergreifende Wohnformen schaffen (Land)', 'Gemeinschaftliches Wohnen kann Alltagskontakt bieten, entsteht aber nur durch Neubau oder Umbau und erreicht wenige Menschen. Wirkung kaum untersucht; Umsetzung dauert mehrere Jahre.', 'offen', null, 'land', null, true, 'blind'),
  (8148, 29, 'Patenschaften und Leihgroßeltern-Projekte unterstützen (Land)', 'Persönliche Kontakte können Alleinstehende erreichen, die Reichweite kleiner Modellprojekte ist aber gering. Einzelangebote wirkten in Übersichten seltener als Gruppenangebote; leicht umsetzbar.', 'offen', null, 'land', null, true, 'blind'),
  (8149, 29, 'Plauderbänke im öffentlichen Raum fördern (Land)', 'Niedrigschwellige Gesprächsgelegenheit mit sehr geringem Aufwand, aber nur flüchtige Kontakte und kaum Wirkung auf bestehende Einsamkeit. Wirkung kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (8150, 29, 'Mehr Schulpsychologie und multiprofessionelle Teams an Schulen (Land)', 'Fachkräfte vor Ort erleichtern das Erkennen von Belastungen und die Hilfesuche; Angebot und Bedarf klaffen bislang auseinander. Wirkung kaum untersucht, Personalgewinnung dauert Jahre.', 'offen', 'https://europepmc.org/articles/PMC13341547', 'land', null, true, 'blind'),
  (8151, 29, 'Psychische Gesundheit und Resilienz im Schulalltag und Unterricht verankern (Land)', 'Unterricht kann Wissen vermitteln, doch Übersichten finden wenig Beleg, dass schulische Präventionsprogramme Angst oder Depression senken; einzelne Ansätze zeigen Effekte. Land kann Lehrpläne anpassen.', 'gemischt', 'https://europepmc.org/article/MED/31734106', 'land', null, true, 'blind'),
  (8152, 29, 'Aufklärung und Entstigmatisierung zu psychischer Gesundheit (Land)', 'Aufklärung und Kontaktprogramme verbessern kurzfristig Einstellungen und Wissen; langfristige Effekte und Wirkung auf die Hilfesuche sind kaum belegt. Gut umsetzbar.', 'gemischt', 'https://europepmc.org/article/MED/26410341', 'land', null, true, 'blind'),
  (8153, 29, 'Fachpersonal zu Stigmatisierung psychischer Erkrankungen schulen (Land)', 'Schulungen können Vorurteile im Umfeld von Betroffenen mindern; Studien zeigen vor allem kurzfristige Einstellungsänderungen, kaum Verhaltens- oder Langzeitwirkung. Leicht umsetzbar.', 'gemischt', 'https://europepmc.org/article/MED/26410341', 'land', null, true, 'blind'),
  (8154, 29, 'Psychosoziale Beratungs- und Kontaktstellen ausbauen (Land)', 'Wohnortnahe, niedrigschwellige Beratung senkt Hürden bei der Hilfesuche und hilft beim Einordnen von Beschwerden. Wirkung einzelner Modelle kaum vergleichend untersucht; Land kann Förderung zügig ausweiten.', 'offen', null, 'land', null, true, 'blind'),
  (8155, 29, 'Krisendienste und Krisentelefone ausbauen und sichern (Land)', 'Krisenmodelle sind laut Cochrane-Übersicht gangbar und werden gut angenommen, die Studienlage ist aber klein und von geringer bis mäßiger Qualität. Flächendeckender Aufbau braucht Personal und Zeit.', 'gemischt', 'https://europepmc.org/article/MED/26633650', 'land', null, true, 'blind'),
  (8156, 29, 'Niedrigschwellige Anlaufstellen und Hilfen für junge Menschen in Krisen (Land)', 'Anlaufstellen ohne Termin und Diagnose erleichtern jungen Menschen den ersten Schritt zur Hilfe. Wirkung kaum vergleichend untersucht; Länder und Kommunen können Standorte rasch fördern.', 'offen', null, 'land', null, true, 'blind'),
  (8157, 29, 'Lotsen- und Vermittlungsangebote in die psychische Versorgung (Land)', 'Lotsen helfen, vorhandene Angebote zu finden, schaffen aber keine zusätzlichen Behandlungsplätze. Wirkung auf Wartezeiten und Hilfesuche kaum untersucht; gut umsetzbar.', 'offen', null, 'land', null, true, 'blind'),
  (8158, 29, 'Sozialpsychiatrische Dienste und aufsuchende psychosoziale Hilfen stärken (Land)', 'Bestehende kommunale Dienste erreichen auch Menschen, die von sich aus keine Hilfe suchen. Wirkung der Ausbaustufen kaum untersucht; Land kann Mittel und Aufgaben zügig anpassen.', 'offen', null, 'land', null, true, 'blind'),
  (8159, 29, 'Suizidprävention verankern und Hilfsangebote vernetzen (Land)', 'Eine Übersicht sieht keine Einzelstrategie klar im Vorteil; schulische Aufklärung senkte Suizidversuche, Telefon- und Internethilfen sind noch zu wenig untersucht. Rechtlich und finanziell gut umsetzbar.', 'gemischt', 'https://europepmc.org/article/MED/27289303', 'land', null, true, 'blind'),
  (8160, 29, 'Digitale Mental-Health-Angebote in der Hochschulversorgung (Land)', 'Eine Meta-Analyse von 21 Studien findet mittlere Effekte digitaler Angebote bei Depression und Angst von Studierenden. Sie senken die Hürde zur Hilfe, wirken aber auf Symptome, nicht auf das Erkennen. Gut umsetzbar.', 'belegt', 'https://europepmc.org/article/MED/40033658', 'land', null, true, 'blind'),
  (8161, 29, 'Jungenarbeit und geschlechtersensible Pädagogik stärken (Land)', 'Setzt früh an Rollenbildern an, die später die Hilfesuche hemmen, wirkt aber erst nach Jahren und erreicht nur Teilgruppen. Wirkung auf spätere Hilfesuche kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (8162, 29, 'Niedrige Einkommen steuerlich entlasten (Bund)', 'Entlastet über die Steuer, erreicht aber Armutsgefährdete ohne Steuerlast kaum; der Zusammenhang zwischen mehr Einkommen und weniger Einsamkeit ist nicht kausal belegt. Bund kann es kurzfristig regeln.', 'offen', null, 'bund', null, true, 'blind'),
  (8163, 29, 'Mindest- und Garantierente für Geringverdienende aufstocken (Bund)', 'Hebt Alterseinkommen direkt an; Studien zu Geldleistungen und psychischer Gesundheit sind uneinheitlich, der Einfluss auf Einsamkeit ist kaum untersucht. Kosten erfordern Finanzierung und Vorlauf.', 'gemischt', null, 'bund', null, true, 'blind'),
  (8164, 29, 'Zugang zu freiwilligem Engagement für Benachteiligte verbessern (Bund)', 'Senkt finanzielle und soziale Hürden zur Teilnahme, erreicht aber nur wenige und wirkt eher auf Teilhabe als auf bestehende Einsamkeit. Wirkung kaum untersucht; Bund finanziert Freiwilligendienste bereits.', 'offen', null, 'bund', null, true, 'blind'),
  (8165, 29, 'Wohnortnahe, niedrigschwellige Kinder- und Jugendangebote sichern (Bund)', 'Freizeit- und Bildungsangebote ermöglichen Teilhabe unabhängig vom Einkommen, wirken aber nur mittelbar auf Einsamkeit. Zuständig sind Länder und Kommunen, der Bund kann nur mit Geld beitragen.', 'offen', null, 'bund', null, true, 'blind'),
  (8166, 29, 'Finanzierung der Psychotherapie-Weiterbildung sichern (Bund)', 'Sichert den Nachwuchs, wirkt aber erst nach Jahren und ändert nicht die Zahl der Kassensitze, die die Wartezeit begrenzt. Bund kann die Finanzierung regeln, braucht aber Einigung mit den Kassen.', 'offen', null, 'bund', null, true, 'blind'),
  (8167, 29, 'Bedarfsplanung für psychotherapeutische Kassensitze reformieren (Bund)', 'Mehr Kassensitze setzen direkt an der Kapazität an; Befragungen sehen fehlende Termine als Hauptengpass. Wirkung bisheriger Reformen nur teils belegt. Bund und Selbstverwaltung können es regeln.', 'offen', 'https://europepmc.org/articles/PMC13288593', 'bund', null, true, 'blind'),
  (8168, 29, 'Kostenerstattung für Psychotherapie bei Wartezeiten erleichtern (Bund)', 'Überbrückt Wartezeit über Privatpraxen, solange es dort freie Plätze gibt; das Gesamtangebot wächst nicht. Wirkung kaum untersucht, rechtlich leicht änderbar.', 'offen', null, 'bund', null, true, 'blind'),
  (8169, 29, 'Therapie- und Versorgungsangebote bedarfsgerecht ausbauen (Bund)', 'Ohne benannten Weg bleibt unklar, wie Plätze entstehen; die Versorgung gilt als unzureichend. Zusage lässt sich rechtlich leicht fassen, die Wirkung hängt von der Umsetzung ab.', 'offen', 'https://europepmc.org/article/MED/40034167', 'bund', null, true, 'blind'),
  (8170, 29, 'Mehr Stellen für Schulpsychologie und Schulsozialarbeit (Bund)', 'Fachkräfte an Schulen erleichtern das Erkennen von Belastungen und die Hilfesuche. Schulen sind Ländersache, der Bund kann nur über Förderprogramme oder Vereinbarungen beitragen. Wirkung kaum untersucht.', 'offen', 'https://europepmc.org/articles/PMC13341547', 'bund', null, true, 'blind'),
  (8585, 29, 'Resilienzförderung ab der Kita und Fortbildung von Lehr- und Fachkräften unterstützen (Bund)', 'Früh ansetzende Förderung und geschulte Fachkräfte können Belastungen eher erkennen; Übersichten finden aber wenig Beleg, dass Präventionsprogramme in Bildungseinrichtungen Angst oder Depression senken. Kita und Schule sind Ländersache, der Bund kann nur fördern.', 'gemischt', 'https://europepmc.org/article/MED/31734106', 'bund', null, true, 'blind')
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
  evidenz = excluded.evidenz, beleg_studie_url = excluded.beleg_studie_url, ebene = excluded.ebene,
  entspricht = excluded.entspricht, ki_entwurf = excluded.ki_entwurf, entwurf_herkunft = excluded.entwurf_herkunft;

delete from public.instrumente where thema_id = 29 and id not in (8142, 8143, 8144, 8145, 8146, 8147, 8148, 8149, 8150, 8151, 8152, 8153, 8154, 8155, 8156, 8157, 8158, 8159, 8160, 8161, 8162, 8163, 8164, 8165, 8166, 8167, 8168, 8169, 8170, 8585);

insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft) values
  (8171, 29, 11, null, 'Bestehende Netzwerke gegen Einsamkeit mit Nachbarschaftshilfen und Beratungsangeboten weiter unterstützen', '{2901,2903}', null, 1, 2, null, 'Bloße Weiterförderung bestehender Netzwerke schafft kaum neue Angebote. Zuständig sind Länder und Kommunen; der Bund kann nur mit Programmen und Geld beitragen. Wirkung kaum untersucht.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=63', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8172, 29, 11, null, 'Ambulante und stationäre Angebote für psychische Erkrankungen bedarfsgerecht verbessern', '{2905}', 8169, 1, 3, null, 'Ohne benannten Weg bleibt unklar, wie Plätze entstehen; die Versorgung gilt als unzureichend. Zusage lässt sich rechtlich leicht fassen, die Wirkung hängt von der Umsetzung ab.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=70', 'https://europepmc.org/article/MED/40034167', 'offen', '2026-10-06', false, true, 'blind'),
  (8173, 29, 11, 'BE', 'Lokale Kiez- und Nachbarschaftstreffen sowie wöchentliche Einsamkeitssprechstunden in Stadtteilzentren fördern.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=110', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8174, 29, 11, 'BE', 'Plauderbänke als Orte für Austausch und offene Gespräche fördern.', '{2901}', 8149, 1, 3, null, 'Niedrigschwellige Gesprächsgelegenheit mit sehr geringem Aufwand, aber nur flüchtige Kontakte und kaum Wirkung auf bestehende Einsamkeit. Wirkung kaum untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=110', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8175, 29, 11, 'BE', 'Ein Landesprogramm für psychische Gesundheit und schulpsychologische Angebote ausbauen sowie Prävention und frühe Hilfen im Schulalltag verankern.', '{2903}', 8150, 2, 2, null, 'Fachkräfte vor Ort erleichtern das Erkennen von Belastungen und die Hilfesuche; Angebot und Bedarf klaffen bislang auseinander. Wirkung kaum untersucht, Personalgewinnung dauert Jahre.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=61', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-06', false, true, 'blind'),
  (8176, 29, 11, 'BE', 'Niedrigschwellige Hilfen für junge Menschen in Krisen und mit psychischen Problemen an weiteren Standorten anbieten.', '{2903}', 8156, 2, 3, null, 'Anlaufstellen ohne Termin und Diagnose erleichtern jungen Menschen den ersten Schritt zur Hilfe. Wirkung kaum vergleichend untersucht; Länder und Kommunen können Standorte rasch fördern.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=98', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8177, 29, 11, 'MV', 'Netzwerke, ehrenamtliches Engagement und generationenübergreifende Wohnformen zur Stärkung des gesellschaftlichen Zusammenhalts fördern.', '{2901}', null, 1, 3, null, 'Allgemeine Absicht, Netzwerke, Ehrenamt und Wohnformen zu fördern, ohne konkreten Weg oder Zielgruppe. Wirkung auf Einsamkeit kaum untersucht, leicht umsetzbar.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=79', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8178, 29, 11, 'MV', 'Einen Beauftragten für sozialen Zusammenhalt zur Koordination des Vorgehens gegen Einsamkeit einsetzen.', '{2901}', 8143, 1, 3, null, 'Strategie und Koordination schaffen selbst kein Angebot; die Wirkung hängt von den Maßnahmen ab, die daraus folgen. Wirkung solcher Strukturen kaum untersucht, rechtlich und finanziell leicht umsetzbar.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=79', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8179, 29, 11, 'MV', 'Landesmittel als Kofinanzierung für die Förderung von Mehrgenerationenhäusern bereitstellen.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=97', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8180, 29, 11, 'MV', 'Generationenmanager und Generationenwerker erproben und etablieren.', '{2901}', 8143, 1, 3, null, 'Strategie und Koordination schaffen selbst kein Angebot; die Wirkung hängt von den Maßnahmen ab, die daraus folgen. Wirkung solcher Strukturen kaum untersucht, rechtlich und finanziell leicht umsetzbar.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=97', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8181, 29, 11, 'MV', 'Die Vermittlung generationsübergreifender Wohnpartnerschaften im Konzept „Wohnen für Hilfe“ ausbauen.', '{2901}', 8146, 1, 3, null, 'Bietet Alltagskontakt im selben Haushalt, erreicht aber nur wenige Menschen und setzt passende Wohnungen voraus. Wirkung auf Einsamkeit kaum untersucht; Vermittlung ist schnell aufzubauen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=98', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8182, 29, 11, 'MV', 'Konzepte zur Vermittlung von Wunschgroßeltern zwischen Familien und älteren Menschen stärker unterstützen.', '{2901}', 8148, 1, 3, null, 'Persönliche Kontakte können Alleinstehende erreichen, die Reichweite kleiner Modellprojekte ist aber gering. Einzelangebote wirkten in Übersichten seltener als Gruppenangebote; leicht umsetzbar.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=98', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8183, 29, 11, 'MV', 'Den Sozialpsychiatrischen Dienst zu einer Notfallnummer mit telemedizinischem Bereitschaftsdienst und schneller ärztlicher Beratung weiterentwickeln.', '{2903}', 8155, 2, 2, null, 'Krisenmodelle sind laut Cochrane-Übersicht gangbar und werden gut angenommen, die Studienlage ist aber klein und von geringer bis mäßiger Qualität. Flächendeckender Aufbau braucht Personal und Zeit.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=75', 'https://europepmc.org/article/MED/26633650', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8184, 29, 11, 'ST', 'Orte der Begegnung für ältere Menschen stärken, Vereinsamung entgegenwirken und alternative Wohnformen fördern.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=32', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8185, 29, 11, 'ST', 'Ehrenamtlich getragene Anlaufstellen im ländlichen Raum unterstützen, die das soziale Miteinander sichern.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=70', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8186, 29, 11, 'ST', 'Psychische Gesundheit und Suizidprävention in der Präventionsarbeit stärker berücksichtigen.', '{2903}', 8159, 1, 3, null, 'Eine Übersicht sieht keine Einzelstrategie klar im Vorteil; schulische Aufklärung senkte Suizidversuche, Telefon- und Internethilfen sind noch zu wenig untersucht. Rechtlich und finanziell gut umsetzbar.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=28', 'https://europepmc.org/article/MED/27289303', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8187, 29, 12, null, 'Das Taschengeld im Freiwilligendienst so gestalten, dass Jugendliche aus einkommensärmeren Haushalten teilnehmen können.', '{2902}', 8164, 1, 3, null, 'Senkt finanzielle und soziale Hürden zur Teilnahme, erreicht aber nur wenige und wirkt eher auf Teilhabe als auf bestehende Einsamkeit. Wirkung kaum untersucht; Bund finanziert Freiwilligendienste bereits.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=28', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8188, 29, 12, null, 'Antragsverfahren für Sozialleistungen vereinfachen und zentrale, niedrigschwellige Anlaufstellen entwickeln.', '{2902}', null, 1, 2, null, 'Einfachere Anträge und zentrale Anlaufstellen können die Inanspruchnahme von Leistungen erhöhen, ändern aber kaum die Einkommenshöhe. Anlaufstellen sind kommunal, der Bund kann nur gesetzlich vereinfachen und fördern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=37', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8189, 29, 12, 'BE', 'Senior*innen mit ungenutzten Zimmern und junge Menschen werden für gegenseitige Alltagshilfe und gemeinsames Wohnen vermittelt.', '{2901}', 8146, 1, 3, null, 'Bietet Alltagskontakt im selben Haushalt, erreicht aber nur wenige Menschen und setzt passende Wohnungen voraus. Wirkung auf Einsamkeit kaum untersucht; Vermittlung ist schnell aufzubauen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=20', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8190, 29, 12, 'BE', 'Barrierefreie, bezahlbare Alters-WGs und generationenübergreifende Wohngruppen schaffen.', '{2901}', 8147, 1, 2, null, 'Gemeinschaftliches Wohnen kann Alltagskontakt bieten, entsteht aber nur durch Neubau oder Umbau und erreicht wenige Menschen. Wirkung kaum untersucht; Umsetzung dauert mehrere Jahre.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=17', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8191, 29, 12, 'BE', 'Ein regelmäßiger stadtweiter Aktionstag soll Gemeinschaft in den Kiezen fördern und Großstadtanonymität aufbrechen.', '{2901}', null, 1, 3, null, 'Ein einzelner Aktionstag schafft Kontaktgelegenheiten, aber keine dauerhaften Beziehungen und erreicht Zurückgezogene kaum. Wirkung kaum untersucht, leicht umsetzbar.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=47', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8192, 29, 12, 'BE', 'In jedem Bezirk neue Orte der Begegnung schaffen.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=47', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8193, 29, 12, 'BE', 'Psychische Kontakt- und Beratungsstellen ausbauen und eine niedrigschwellige, wohnortnahe Versorgung ermöglichen.', '{2903}', 8154, 2, 3, null, 'Wohnortnahe, niedrigschwellige Beratung senkt Hürden bei der Hilfesuche und hilft beim Einordnen von Beschwerden. Wirkung einzelner Modelle kaum vergleichend untersucht; Land kann Förderung zügig ausweiten.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=34', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8194, 29, 12, 'BE', 'Niedrigschwellige Anlaufstellen für Jugendliche in seelischen Krisen ausbauen.', '{2903}', 8156, 2, 3, null, 'Anlaufstellen ohne Termin und Diagnose erleichtern jungen Menschen den ersten Schritt zur Hilfe. Wirkung kaum vergleichend untersucht; Länder und Kommunen können Standorte rasch fördern.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=38', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8195, 29, 12, 'BE', 'Psychosoziale Beratung für wohnungslose Menschen als Teil ausgebauter und verstetigter Beratungs- und Versorgungsangebote.', '{2903}', 8154, 2, 3, null, 'Wohnortnahe, niedrigschwellige Beratung senkt Hürden bei der Hilfesuche und hilft beim Einordnen von Beschwerden. Wirkung einzelner Modelle kaum vergleichend untersucht; Land kann Förderung zügig ausweiten.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=51', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8196, 29, 12, 'BE', 'Die mentale Gesundheit in Schulen durch mehr multiprofessionelles Personal, insbesondere Schulpsychologie und Gesundheitsfachkräfte, stärken.', '{2903}', 8150, 2, 2, null, 'Fachkräfte vor Ort erleichtern das Erkennen von Belastungen und die Hilfesuche; Angebot und Bedarf klaffen bislang auseinander. Wirkung kaum untersucht, Personalgewinnung dauert Jahre.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=42', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-06', false, true, 'blind'),
  (8197, 29, 12, 'MV', 'Landesprogramm zur Schaffung von Begegnungsorten weiter unterstützen', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=33', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8198, 29, 12, 'MV', 'Jugendclubs, soziokulturelle Zentren und Dritte Orte stärken und neu schaffen', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=36', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8199, 29, 12, 'MV', 'Stigmatisierung psychischer Erkrankungen entgegenwirken und Diagnostik und Therapie verbessern', '{2903}', 8152, 1, 3, null, 'Aufklärung und Kontaktprogramme verbessern kurzfristig Einstellungen und Wissen; langfristige Effekte und Wirkung auf die Hilfesuche sind kaum belegt. Gut umsetzbar.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=31', 'https://europepmc.org/article/MED/26410341', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8200, 29, 12, 'ST', 'Wohnortnahe Versorgungsnetzwerke und organisierte Nachbarschaftshilfe stärken', '{2901}', 8144, 2, 3, null, 'Erreicht auch Menschen, die nicht von sich aus Treffpunkte aufsuchen. Besuchsangebote wirkten in Übersichten seltener als Gruppenangebote (60 % gegenüber 79 % der Studien mit Verbesserung). Gut umsetzbar.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=14', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8201, 29, 12, 'ST', 'Eine landesweite Strategie gegen Einsamkeit entwickeln', '{2901}', 8143, 1, 3, null, 'Strategie und Koordination schaffen selbst kein Angebot; die Wirkung hängt von den Maßnahmen ab, die daraus folgen. Wirkung solcher Strukturen kaum untersucht, rechtlich und finanziell leicht umsetzbar.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=34', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8202, 29, 12, 'ST', 'Die Engagementstrategie finanziell stärken und weiterentwickeln', '{2901}', 8145, 1, 3, null, 'Vereine und Engagement bieten Kontaktgelegenheiten, die Förderung wirkt aber nur indirekt und erreicht Verwitwete nicht gezielt. Wirkung auf Einsamkeit kaum untersucht; leicht umsetzbar.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=34', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8203, 29, 12, 'ST', 'Den Engagementfonds niedrigschwellig ausbauen und Initiativen unterstützen', '{2901}', 8145, 1, 3, null, 'Vereine und Engagement bieten Kontaktgelegenheiten, die Förderung wirkt aber nur indirekt und erreicht Verwitwete nicht gezielt. Wirkung auf Einsamkeit kaum untersucht; leicht umsetzbar.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=34', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8204, 29, 12, 'ST', 'Freiwilligenagenturen und Engagementzentren strukturell fördern', '{2901}', 8145, 1, 3, null, 'Vereine und Engagement bieten Kontaktgelegenheiten, die Förderung wirkt aber nur indirekt und erreicht Verwitwete nicht gezielt. Wirkung auf Einsamkeit kaum untersucht; leicht umsetzbar.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=34', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8205, 29, 12, 'ST', 'Stadtteilfeste, Begegnungsformate und Vernetzung vor Ort finanziell unterstützen', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=34', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8206, 29, 12, 'ST', 'Prävention und Beratung zu psychischer Gesundheit ausbauen', '{2903}', 8154, 2, 3, null, 'Wohnortnahe, niedrigschwellige Beratung senkt Hürden bei der Hilfesuche und hilft beim Einordnen von Beschwerden. Wirkung einzelner Modelle kaum vergleichend untersucht; Land kann Förderung zügig ausweiten.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=15', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8207, 29, 12, 'ST', 'Gemeindepsychiatrische Verbünde stärken', '{2903}', 8158, 2, 3, null, 'Bestehende kommunale Dienste erreichen auch Menschen, die von sich aus keine Hilfe suchen. Wirkung der Ausbaustufen kaum untersucht; Land kann Mittel und Aufgaben zügig anpassen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=15', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8208, 29, 12, 'ST', 'Passgenaue Beratung bei psychischen Belastungen queerer Menschen anbieten', '{2903}', 8154, 2, 3, null, 'Wohnortnahe, niedrigschwellige Beratung senkt Hürden bei der Hilfesuche und hilft beim Einordnen von Beschwerden. Wirkung einzelner Modelle kaum vergleichend untersucht; Land kann Förderung zügig ausweiten.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=15', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8209, 29, 12, 'ST', 'Die Jungenarbeit im Land strukturell stärken', '{2904}', 8161, 1, 3, null, 'Setzt früh an Rollenbildern an, die später die Hilfesuche hemmen, wirkt aber erst nach Jahren und erreicht nur Teilgruppen. Wirkung auf spätere Hilfesuche kaum untersucht.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=27', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8210, 29, 13, null, 'Eine Garantierente für mehr Menschen mit geringem Einkommen weiterentwickeln.', '{2902}', 8163, 2, 2, null, 'Hebt Alterseinkommen direkt an; Studien zu Geldleistungen und psychischer Gesundheit sind uneinheitlich, der Einfluss auf Einsamkeit ist kaum untersucht. Kosten erfordern Finanzierung und Vorlauf.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=97', null, 'gemischt', '2026-10-06', false, true, 'blind'),
  (8211, 29, 13, null, 'Ein bundesweit vergünstigtes Nahverkehrsangebot für Menschen mit geringem Einkommen entwickeln.', '{2902}', null, 1, 2, null, 'Ein günstiges Ticket erleichtert Teilhabe finanziell, wirkt aber nur mittelbar auf Einsamkeit; Wirkung kaum untersucht. Nahverkehr ist Ländersache, der Bund braucht eine Vereinbarung und muss Mittel bereitstellen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=49', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8212, 29, 13, null, 'Den Zugang zum freiwilligen Engagement für Menschen mit geringem Einkommen verbessern.', '{2902}', 8164, 1, 3, null, 'Senkt finanzielle und soziale Hürden zur Teilnahme, erreicht aber nur wenige und wirkt eher auf Teilhabe als auf bestehende Einsamkeit. Wirkung kaum untersucht; Bund finanziert Freiwilligendienste bereits.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=111', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8213, 29, 13, null, 'Sozial gestaffelte Unterstützungsmöglichkeiten für Freiwilligendienste schaffen.', '{2902}', 8164, 1, 3, null, 'Senkt finanzielle und soziale Hürden zur Teilnahme, erreicht aber nur wenige und wirkt eher auf Teilhabe als auf bestehende Einsamkeit. Wirkung kaum untersucht; Bund finanziert Freiwilligendienste bereits.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=112', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8214, 29, 13, null, 'Engagementstrukturen für ältere Menschen ausbauen, damit auch bisher schwer erreichbare Personen teilnehmen können.', '{2902}', 8164, 1, 3, null, 'Senkt finanzielle und soziale Hürden zur Teilnahme, erreicht aber nur wenige und wirkt eher auf Teilhabe als auf bestehende Einsamkeit. Wirkung kaum untersucht; Bund finanziert Freiwilligendienste bereits.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=86', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8215, 29, 13, null, 'Die Angebote der Mental Health Coaches an Schulen ausbauen.', '{2903}', 8170, 2, 2, null, 'Fachkräfte an Schulen erleichtern das Erkennen von Belastungen und die Hilfesuche. Schulen sind Ländersache, der Bund kann nur über Förderprogramme oder Vereinbarungen beitragen. Wirkung kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=77', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-06', false, true, 'blind'),
  (8216, 29, 13, null, 'Mehr Stellen für Schulsozialarbeit und Schulpsychologie in multiprofessionellen Teams schaffen.', '{2903}', 8170, 2, 2, null, 'Fachkräfte an Schulen erleichtern das Erkennen von Belastungen und die Hilfesuche. Schulen sind Ländersache, der Bund kann nur über Förderprogramme oder Vereinbarungen beitragen. Wirkung kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=77', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-06', false, true, 'blind'),
  (8217, 29, 13, null, 'Therapieplätze bedarfsgerecht ausbauen.', '{2905}', 8169, 1, 3, null, 'Ohne benannten Weg bleibt unklar, wie Plätze entstehen; die Versorgung gilt als unzureichend. Zusage lässt sich rechtlich leicht fassen, die Wirkung hängt von der Umsetzung ab.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=95', 'https://europepmc.org/article/MED/40034167', 'offen', '2026-10-06', false, true, 'blind'),
  (8218, 29, 13, null, 'Psychiatrisch-psychosoziale Krisendienste bedarfsgerecht ausbauen.', '{2903}', null, 2, 2, null, 'Krisenmodelle sind laut Cochrane-Übersicht gangbar, die Studienlage ist klein. Zuständig sind die Länder; der Bund kann nur mit Geld oder Vereinbarungen beitragen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=95', 'https://europepmc.org/article/MED/26633650', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8219, 29, 13, null, 'Psychosoziale Zentren für Geflüchtete stärken.', '{2903}', null, 2, 3, null, 'Spezialisierte, niedrigschwellige Beratung mit Sprachmittlung hilft Geflüchteten bei der Hilfesuche, erreicht aber nur diese Gruppe. Wirkung kaum untersucht; der Bund fördert die Zentren bereits.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=95', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8220, 29, 13, null, 'Die Bedarfsplanung für psychotherapeutische Angebote modernisieren.', '{2905}', 8167, 2, 3, null, 'Mehr Kassensitze setzen direkt an der Kapazität an; Befragungen sehen fehlende Termine als Hauptengpass. Wirkung bisheriger Reformen nur teils belegt. Bund und Selbstverwaltung können es regeln.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=95', 'https://europepmc.org/articles/PMC13288593', 'offen', '2026-10-06', false, true, 'blind'),
  (8221, 29, 13, null, 'Die angemessene Finanzierung der psychotherapeutischen Weiterbildung sicherstellen.', '{2905}', 8166, 1, 2, null, 'Sichert den Nachwuchs, wirkt aber erst nach Jahren und ändert nicht die Zahl der Kassensitze, die die Wartezeit begrenzt. Bund kann die Finanzierung regeln, braucht aber Einigung mit den Kassen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=95', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8222, 29, 13, 'BE', 'Begegnungsräume durch generationenübergreifende Treffpunkte und bestehende Begegnungsstätten in allen Bezirken schaffen und weiterentwickeln.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=218', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8223, 29, 13, 'BE', 'Gemeinschaftliche Flächen in Quartieren so gestalten, dass sie Nachbarschaft und Begegnung fördern.', '{2901}', null, 1, 3, null, 'Gemeinsam gestaltete Flächen können zufällige Begegnungen fördern, schaffen aber kein Angebot für Alleinstehende. Wirkung auf Einsamkeit kaum untersucht, leicht umsetzbar.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=63', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8224, 29, 13, 'BE', 'Eine Landesstrategie gegen Einsamkeit mit gezielten Maßnahmen für sozial isolierte Menschen entwickeln.', '{2901}', 8143, 1, 3, null, 'Strategie und Koordination schaffen selbst kein Angebot; die Wirkung hängt von den Maßnahmen ab, die daraus folgen. Wirkung solcher Strukturen kaum untersucht, rechtlich und finanziell leicht umsetzbar.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=74', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8225, 29, 13, 'BE', 'Mit mobiler Stadtteilarbeit Menschen erreichen, für die ein Nachbarschaftszentrum zu schwer zugänglich ist.', '{2901}', 8144, 2, 3, null, 'Erreicht auch Menschen, die nicht von sich aus Treffpunkte aufsuchen. Besuchsangebote wirkten in Übersichten seltener als Gruppenangebote (60 % gegenüber 79 % der Studien mit Verbesserung). Gut umsetzbar.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=74', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8226, 29, 13, 'BE', 'Gemeinschaftliche Wohnformen unterstützen, die Vereinsamung vorbeugen und gegenseitige Hilfe fördern.', '{2901}', 8147, 1, 2, null, 'Gemeinschaftliches Wohnen kann Alltagskontakt bieten, entsteht aber nur durch Neubau oder Umbau und erreicht wenige Menschen. Wirkung kaum untersucht; Umsetzung dauert mehrere Jahre.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=219', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8227, 29, 13, 'BE', 'Das Projekt der Plauderbänke in den Bezirken fördern.', '{2901}', 8149, 1, 3, null, 'Niedrigschwellige Gesprächsgelegenheit mit sehr geringem Aufwand, aber nur flüchtige Kontakte und kaum Wirkung auf bestehende Einsamkeit. Wirkung kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=219', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8228, 29, 13, 'BE', 'Psychische Gesundheit durch Entstigmatisierung, Prävention und Früherkennung stärken.', '{2903,2904}', 8152, 1, 3, null, 'Aufklärung und Kontaktprogramme verbessern kurzfristig Einstellungen und Wissen; langfristige Effekte und Wirkung auf die Hilfesuche sind kaum belegt. Gut umsetzbar.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=204', 'https://europepmc.org/article/MED/26410341', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8229, 29, 13, 'BE', 'Psychiatrische Einrichtungen fördern und niedrigschwellige Lotsen- und Vermittlungsangebote für passende Psychotherapie ausbauen.', '{2903}', 8157, 1, 3, null, 'Lotsen helfen, vorhandene Angebote zu finden, schaffen aber keine zusätzlichen Behandlungsplätze. Wirkung auf Wartezeiten und Hilfesuche kaum untersucht; gut umsetzbar.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=204', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8230, 29, 13, 'BE', 'Integrierte, niedrigschwellige, aufsuchende und multiprofessionelle Hilfs- und Krisenangebote in allen Bezirken ausbauen.', '{2903}', 8155, 2, 2, null, 'Krisenmodelle sind laut Cochrane-Übersicht gangbar und werden gut angenommen, die Studienlage ist aber klein und von geringer bis mäßiger Qualität. Flächendeckender Aufbau braucht Personal und Zeit.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=204', 'https://europepmc.org/article/MED/26633650', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8231, 29, 13, 'BE', 'Präventions- und Unterstützungsangebote für Kinder und Jugendliche mit Schulpsychologie, Jugendpsychiatrie-Teams und früher Hilfe im sozialen Umfeld ausbauen.', '{2903}', 8150, 2, 2, null, 'Fachkräfte vor Ort erleichtern das Erkennen von Belastungen und die Hilfesuche; Angebot und Bedarf klaffen bislang auseinander. Wirkung kaum untersucht, Personalgewinnung dauert Jahre.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=204', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-06', false, true, 'blind'),
  (8232, 29, 13, 'BE', 'Die anonyme Telefonsorge der „Nummer gegen Kummer“ für Kinder und Jugendliche dauerhaft erhalten.', '{2903}', 8155, 2, 2, null, 'Krisenmodelle sind laut Cochrane-Übersicht gangbar und werden gut angenommen, die Studienlage ist aber klein und von geringer bis mäßiger Qualität. Flächendeckender Aufbau braucht Personal und Zeit.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=204', 'https://europepmc.org/article/MED/26633650', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8233, 29, 13, 'BE', 'Suizidprävention systematisch verankern und Hilfsangebote stärker vernetzen und gezielt ausbauen.', '{2903}', 8159, 1, 3, null, 'Eine Übersicht sieht keine Einzelstrategie klar im Vorteil; schulische Aufklärung senkte Suizidversuche, Telefon- und Internethilfen sind noch zu wenig untersucht. Rechtlich und finanziell gut umsetzbar.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=204', 'https://europepmc.org/article/MED/27289303', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8234, 29, 13, 'BE', 'Psychosoziale und psychotherapeutische Versorgung für Geflüchtete stärken und niedrigschwelligen, bedarfsgerechten Zugang ermöglichen.', '{2903}', 8154, 2, 3, null, 'Wohnortnahe, niedrigschwellige Beratung senkt Hürden bei der Hilfesuche und hilft beim Einordnen von Beschwerden. Wirkung einzelner Modelle kaum vergleichend untersucht; Land kann Förderung zügig ausweiten.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=143', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8235, 29, 13, 'BE', 'Flächendeckende integrierte Gesundheitszentren mit therapeutischen, psychosozialen und präventiven Angeboten aufbauen.', '{2903}', null, 1, 2, null, 'Gesundheitszentren bündeln Angebote und können Hürden senken, der Zusammenhang mit dem Erkennen psychischer Symptome ist aber indirekt. Wirkung kaum untersucht; flächendeckender Aufbau dauert Jahre.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=202', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8236, 29, 13, 'BE', 'Gesundheitsförderung mit Schwerpunkt psychische Gesundheit verbindlich in Kitas, Schulen, Betrieben und Senior*inneneinrichtungen integrieren.', '{2903}', 8151, 1, 3, null, 'Unterricht kann Wissen vermitteln, doch Übersichten finden wenig Beleg, dass schulische Präventionsprogramme Angst oder Depression senken; einzelne Ansätze zeigen Effekte. Land kann Lehrpläne anpassen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=208', 'https://europepmc.org/article/MED/31734106', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8237, 29, 13, 'BE', 'Psychosoziale Versorgung durch Zusammenarbeit von Straßensozialarbeit und psychosozialen Diensten direkt in den Kiezen stärken.', '{2903}', 8158, 2, 3, null, 'Bestehende kommunale Dienste erreichen auch Menschen, die von sich aus keine Hilfe suchen. Wirkung der Ausbaustufen kaum untersucht; Land kann Mittel und Aufgaben zügig anpassen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=73', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8238, 29, 13, 'MV', 'Kommunale Nachbarschaftstreffs als Orte der Geselligkeit und des gemeinsamen Arbeitens schaffen; Veranstaltungen für Menschen über 65 kostenlos anbieten.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://gruene-mv.de/?wpdmdl=33772#page=63', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8239, 29, 13, 'MV', 'Mentale Gesundheit an Schulen durch Aufklärung, geschultes Personal und verlässliche Unterstützung fördern.', '{2903}', 8151, 1, 3, null, 'Unterricht kann Wissen vermitteln, doch Übersichten finden wenig Beleg, dass schulische Präventionsprogramme Angst oder Depression senken; einzelne Ansätze zeigen Effekte. Land kann Lehrpläne anpassen.', 'https://gruene-mv.de/?wpdmdl=33772#page=59', 'https://europepmc.org/article/MED/31734106', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8240, 29, 13, 'MV', 'Flächendeckende Krisendienste für schnelle und niedrigschwellige Hilfe in akuten Situationen aufbauen.', '{2903}', 8155, 2, 2, null, 'Krisenmodelle sind laut Cochrane-Übersicht gangbar und werden gut angenommen, die Studienlage ist aber klein und von geringer bis mäßiger Qualität. Flächendeckender Aufbau braucht Personal und Zeit.', 'https://gruene-mv.de/?wpdmdl=33772#page=59', 'https://europepmc.org/article/MED/26633650', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8241, 29, 13, 'MV', 'Psychosoziale Beratung flächendeckend und auskömmlich finanzieren und digitale Angebote ermöglichen.', '{2903}', 8154, 2, 3, null, 'Wohnortnahe, niedrigschwellige Beratung senkt Hürden bei der Hilfesuche und hilft beim Einordnen von Beschwerden. Wirkung einzelner Modelle kaum vergleichend untersucht; Land kann Förderung zügig ausweiten.', 'https://gruene-mv.de/?wpdmdl=33772#page=64', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8242, 29, 13, 'MV', 'Stigmatisierung psychisch erkrankter Menschen abbauen.', '{2904}', 8152, 1, 3, null, 'Aufklärung und Kontaktprogramme verbessern kurzfristig Einstellungen und Wissen; langfristige Effekte und Wirkung auf die Hilfesuche sind kaum belegt. Gut umsetzbar.', 'https://gruene-mv.de/?wpdmdl=33772#page=60', 'https://europepmc.org/article/MED/26410341', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8243, 29, 13, 'ST', 'Bestehende Treffpunkte sichern und moderne Dorfzentren mit gebündelten Alltagsangeboten ermöglichen.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=39', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8244, 29, 13, 'ST', 'Quartiersansätze gegen Einsamkeit bündeln, unterstützen und finanzieren.', '{2901}', 8143, 1, 3, null, 'Strategie und Koordination schaffen selbst kein Angebot; die Wirkung hängt von den Maßnahmen ab, die daraus folgen. Wirkung solcher Strukturen kaum untersucht, rechtlich und finanziell leicht umsetzbar.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=39', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8245, 29, 13, 'ST', 'Jugendorte für freie Treffen und Austausch in kleineren Städten und Gemeinden schaffen und ausbauen.', '{2901}', null, 1, 3, null, 'Jugendorte bieten freie Treffen, erreichen aber vor allem junge Menschen und nicht die Gruppe der Verwitweten. Wirkung auf Einsamkeit kaum untersucht, leicht umsetzbar.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=56', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8246, 29, 13, 'ST', 'Kitas als soziale Treffpunkte und offene Familienzentren weiterentwickeln.', '{2901}', null, 1, 3, null, 'Familienzentren bieten Kontakt für Familien, erreichen aber kaum Verwitwete oder Ältere. Wirkung auf Einsamkeit kaum untersucht, Ausbau ist gut umsetzbar.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=58', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8247, 29, 13, 'ST', 'Selbsthilfegruppen unterstützen, um Engagement und soziale Teilhabe zu fördern.', '{2901}', 8145, 1, 3, null, 'Vereine und Engagement bieten Kontaktgelegenheiten, die Förderung wirkt aber nur indirekt und erreicht Verwitwete nicht gezielt. Wirkung auf Einsamkeit kaum untersucht; leicht umsetzbar.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=74', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8248, 29, 13, 'ST', 'Patenschaften und Leihgroßeltern als generationenübergreifende Gemeinschaftsprojekte unterstützen.', '{2901}', 8148, 1, 3, null, 'Persönliche Kontakte können Alleinstehende erreichen, die Reichweite kleiner Modellprojekte ist aber gering. Einzelangebote wirkten in Übersichten seltener als Gruppenangebote; leicht umsetzbar.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=86', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8249, 29, 13, 'ST', 'Niedrigschwellige Beratung und Krisenintervention zur psychischen Gesundheit für Jugendliche ausbauen.', '{2903}', 8156, 2, 3, null, 'Anlaufstellen ohne Termin und Diagnose erleichtern jungen Menschen den ersten Schritt zur Hilfe. Wirkung kaum vergleichend untersucht; Länder und Kommunen können Standorte rasch fördern.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=56', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8250, 29, 13, 'ST', 'Beratung, Prävention und Aufklärung zu psychischen Erkrankungen fördern und Stigmatisierungen abbauen.', '{2903,2904}', 8152, 1, 3, null, 'Aufklärung und Kontaktprogramme verbessern kurzfristig Einstellungen und Wissen; langfristige Effekte und Wirkung auf die Hilfesuche sind kaum belegt. Gut umsetzbar.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=84', 'https://europepmc.org/article/MED/26410341', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8251, 29, 13, 'ST', 'Geschlechtersensible Forschung zu Männergesundheit in Ausbildung und Klinikalltag verankern.', '{2904}', null, 1, 3, null, 'Forschung in Ausbildung und Klinikalltag kann Behandler für Männer sensibilisieren, ändert aber kaum die Scham, die Männer von der Hilfesuche abhält. Wirkung kaum untersucht.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=82', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8252, 29, 14, null, 'Babyboomer-Engagement gezielt für Sportangebote und Vereinsarbeit einbinden.', '{2901}', null, 1, 2, null, 'Einbindung der Babyboomer stärkt Vereine, erreicht Verwitwete aber nur mittelbar. Vereinsförderung ist überwiegend Ländersache, der Bund kann über Engagementprogramme beitragen. Wirkung kaum untersucht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=32', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8253, 29, 14, null, 'Psychische Gesundheit durch Entstigmatisierung und niedrigschwellige digitale Angebote stärken.', '{2903}', null, 1, 3, null, 'Entstigmatisierung und digitale Angebote können Hürden senken, die Maßnahme nennt aber keinen konkreten Weg. Digitale Angebote wirken auf Symptome, Entstigmatisierung meist nur kurzfristig.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=34', 'https://europepmc.org/article/MED/26410341', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8254, 29, 14, null, 'Suizidprävention spürbar ausbauen und Menschen mit Suizidgedanken Unterstützung zusichern.', '{2903}', null, 1, 2, null, 'Eine Übersicht sieht keine Einzelstrategie klar im Vorteil; ohne konkrete Bausteine bleibt die Wirkung offen. Suizidprävention ist überwiegend Länder- und Kassenaufgabe, der Bund kann mit Strategie und Geld beitragen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=34', 'https://europepmc.org/article/MED/27289303', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8255, 29, 14, null, 'Das Kostenerstattungsverfahren während der Wartezeit vereinfachen und standardisieren.', '{2905}', 8168, 1, 3, null, 'Überbrückt Wartezeit über Privatpraxen, solange es dort freie Plätze gibt; das Gesamtangebot wächst nicht. Wirkung kaum untersucht, rechtlich leicht änderbar.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=34', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8256, 29, 14, 'BE', 'Den generationsübergreifenden Dialog vertiefen.', '{2901}', 8148, 1, 3, null, 'Persönliche Kontakte können Alleinstehende erreichen, die Reichweite kleiner Modellprojekte ist aber gering. Einzelangebote wirkten in Übersichten seltener als Gruppenangebote; leicht umsetzbar.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=119', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8257, 29, 14, 'BE', 'Eltern für traditionelle Rollenbilder sensibilisieren und geschlechtersensible Erziehung fördern.', '{2904}', 8161, 1, 3, null, 'Setzt früh an Rollenbildern an, die später die Hilfesuche hemmen, wirkt aber erst nach Jahren und erreicht nur Teilgruppen. Wirkung auf spätere Hilfesuche kaum untersucht.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=81', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8258, 29, 14, 'MV', 'Senioren- und Mehrgenerationenbegegnungsstätten mit generationsübergreifenden Freizeitprogrammen gegen Vereinsamung fördern.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=39', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8259, 29, 14, 'MV', 'Digitale Mental-Health-Angebote und Online-Interventionen in die Regelversorgung an Hochschulen integrieren.', '{2903}', 8160, 2, 3, null, 'Eine Meta-Analyse von 21 Studien findet mittlere Effekte digitaler Angebote bei Depression und Angst von Studierenden. Sie senken die Hürde zur Hilfe, wirken aber auf Symptome, nicht auf das Erkennen. Gut umsetzbar.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=115', 'https://europepmc.org/article/MED/40033658', 'belegt', '2026-10-06', false, true, 'blind'),
  (8260, 29, 14, 'MV', 'Online-Interventionen in den ersten vier bis sechs Wochen bis zur Regelversorgung ohne Verzögerung ermöglichen.', '{2903}', 8160, 2, 3, null, 'Eine Meta-Analyse von 21 Studien findet mittlere Effekte digitaler Angebote bei Depression und Angst von Studierenden. Sie senken die Hürde zur Hilfe, wirken aber auf Symptome, nicht auf das Erkennen. Gut umsetzbar.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=115', 'https://europepmc.org/article/MED/40033658', 'belegt', '2026-10-06', false, true, 'blind'),
  (8261, 29, 14, 'ST', 'Orte der Begegnung für zivilgesellschaftliche Initiativen fördern.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=35', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8262, 29, 15, null, 'Erhöhung des einkommensteuerlichen Grundfreibetrags zur Entlastung niedriger Einkommen', '{2902}', 8162, 1, 3, null, 'Entlastet über die Steuer, erreicht aber Armutsgefährdete ohne Steuerlast kaum; der Zusammenhang zwischen mehr Einkommen und weniger Einsamkeit ist nicht kausal belegt. Bund kann es kurzfristig regeln.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=59', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8263, 29, 15, 'BE', 'Einsamkeit im Alter durch gezielte Förderung von Teilhabe und ehrenamtlichem Engagement bekämpfen.', '{2901}', 8145, 1, 3, null, 'Vereine und Engagement bieten Kontaktgelegenheiten, die Förderung wirkt aber nur indirekt und erreicht Verwitwete nicht gezielt. Wirkung auf Einsamkeit kaum untersucht; leicht umsetzbar.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=51', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8264, 29, 15, 'MV', 'Heimatvereine gezielt fördern.', '{2901}', 8145, 1, 3, null, 'Vereine und Engagement bieten Kontaktgelegenheiten, die Förderung wirkt aber nur indirekt und erreicht Verwitwete nicht gezielt. Wirkung auf Einsamkeit kaum untersucht; leicht umsetzbar.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=67', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8265, 29, 15, 'MV', 'Die Zahl der Schulpsychologen am gestiegenen Bedarf ausrichten.', '{2903}', 8150, 2, 2, null, 'Fachkräfte vor Ort erleichtern das Erkennen von Belastungen und die Hilfesuche; Angebot und Bedarf klaffen bislang auseinander. Wirkung kaum untersucht, Personalgewinnung dauert Jahre.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=25', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-06', false, true, 'blind'),
  (8266, 29, 16, null, 'Eine sanktionsfreie Mindestsicherung am Armutsrisiko ausrichten und für Menschen ohne ausreichendes Einkommen oder Vermögen öffnen.', '{2902}', null, 2, 1, null, 'Hebt das Mindesteinkommen direkt auf die Armutsschwelle; Studien zu Geldleistungen und psychischer Gesundheit sind uneinheitlich, zu Einsamkeit kaum vorhanden. Die Kosten sind hoch, die Finanzierung ungeklärt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=15', null, 'gemischt', '2026-10-06', false, true, 'blind'),
  (8267, 29, 16, null, 'Niedrige und mittlere Einkommen steuerlich entlasten.', '{2902}', 8162, 1, 3, null, 'Entlastet über die Steuer, erreicht aber Armutsgefährdete ohne Steuerlast kaum; der Zusammenhang zwischen mehr Einkommen und weniger Einsamkeit ist nicht kausal belegt. Bund kann es kurzfristig regeln.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=11', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8268, 29, 16, null, 'Kinder- und Jugendangebote wohnortnah, barrierefrei und gebührenfrei zugänglich machen und kommunal finanzieren.', '{2902}', 8165, 1, 2, null, 'Freizeit- und Bildungsangebote ermöglichen Teilhabe unabhängig vom Einkommen, wirken aber nur mittelbar auf Einsamkeit. Zuständig sind Länder und Kommunen, der Bund kann nur mit Geld beitragen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=16', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8269, 29, 16, null, 'Ein kostenloses bundesweites Senior*innen-Ticket für Mobilität und soziale Teilhabe einführen.', '{2902}', null, 1, 1, null, 'Ein kostenloses Ticket erleichtert Teilhabe finanziell, wirkt aber nur mittelbar auf Einsamkeit; Wirkung kaum untersucht. Nahverkehr ist Ländersache, die Kosten für alle Älteren sind sehr hoch und ungeklärt finanziert.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=17', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8270, 29, 16, null, 'Psychotherapien bis zu ausreichender Kassenzulassung unbürokratisch über Kostenerstattung ermöglichen.', '{2905}', 8168, 1, 3, null, 'Überbrückt Wartezeit über Privatpraxen, solange es dort freie Plätze gibt; das Gesamtangebot wächst nicht. Wirkung kaum untersucht, rechtlich leicht änderbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=19', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8271, 29, 16, null, 'Die Bedarfsplanung für psychotherapeutische Kassensitze am tatsächlichen Bedarf ausrichten.', '{2905}', 8167, 2, 3, null, 'Mehr Kassensitze setzen direkt an der Kapazität an; Befragungen sehen fehlende Termine als Hauptengpass. Wirkung bisheriger Reformen nur teils belegt. Bund und Selbstverwaltung können es regeln.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=19', 'https://europepmc.org/articles/PMC13288593', 'offen', '2026-10-06', false, true, 'blind'),
  (8272, 29, 16, null, 'Ausbildungskosten künftiger Psychotherapeut*innen deckeln.', '{2905}', 8166, 1, 2, null, 'Sichert den Nachwuchs, wirkt aber erst nach Jahren und ändert nicht die Zahl der Kassensitze, die die Wartezeit begrenzt. Bund kann die Finanzierung regeln, braucht aber Einigung mit den Kassen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=19', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8273, 29, 16, null, 'Psychotherapeut*innen in Ausbildung einen Beschäftigungsstatus mit Zugang zu Tarifstrukturen geben.', '{2905}', 8166, 1, 2, null, 'Sichert den Nachwuchs, wirkt aber erst nach Jahren und ändert nicht die Zahl der Kassensitze, die die Wartezeit begrenzt. Bund kann die Finanzierung regeln, braucht aber Einigung mit den Kassen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=19', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8274, 29, 16, null, 'Die Finanzierung der Psychotherapieausbildung durch Weiterbildungsstätten gesetzlich regeln.', '{2905}', 8166, 1, 2, null, 'Sichert den Nachwuchs, wirkt aber erst nach Jahren und ändert nicht die Zahl der Kassensitze, die die Wartezeit begrenzt. Bund kann die Finanzierung regeln, braucht aber Einigung mit den Kassen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=19', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8275, 29, 16, 'BE', 'Einsamkeitsbeauftragte bei landeseigenen Wohnungsunternehmen sollen ältere Mieter*innen besuchen und nachbarschaftliche Aktivitäten organisieren.', '{2901}', 8144, 2, 3, null, 'Erreicht auch Menschen, die nicht von sich aus Treffpunkte aufsuchen. Besuchsangebote wirkten in Übersichten seltener als Gruppenangebote (60 % gegenüber 79 % der Studien mit Verbesserung). Gut umsetzbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=30', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8276, 29, 16, 'BE', 'Ein Aktionsprogramm soll nachbarschaftliche Angebote in Großsiedlungen fördern und Beteiligungsformate für das Miteinander ausbauen.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=32', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8277, 29, 16, 'BE', 'Kiezkantinen sollen bezahlbare Mahlzeiten und soziale Begegnungsorte in der Nachbarschaft schaffen.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=32', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8278, 29, 16, 'BE', 'Pilotprojekte für Sorgezentren sollen Nachbarschaft, gemeinsame Sorgearbeit und Selbstorganisation vor Ort ermöglichen.', '{2901}', null, 1, 3, null, 'Pilotprojekte schaffen Orte für Nachbarschaft, erreichen aber nur wenige Standorte und liefern erst später Erkenntnisse. Wirkung kaum untersucht, leicht umsetzbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=43', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8279, 29, 16, 'BE', 'Ein verbindliches Landesprogramm soll Einsamkeit durch aufsuchende Maßnahmen und bezirkliche Link-Worker bekämpfen.', '{2901}', null, 2, 2, null, 'Link-Worker vermitteln Isolierte in Angebote vor Ort; alle neun ausgewerteten Studien berichten positive Effekte, sie sind aber klein und uneinheitlich. Neue Stellen und Strukturen brauchen Aufbauzeit.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=113', 'https://europepmc.org/article/MED/34159848', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8280, 29, 16, 'BE', 'In jedem Bezirk soll eine Einsamkeitsbeauftragte oder ein Einsamkeitsbeauftragter eingesetzt werden.', '{2901}', 8143, 1, 3, null, 'Strategie und Koordination schaffen selbst kein Angebot; die Wirkung hängt von den Maßnahmen ab, die daraus folgen. Wirkung solcher Strukturen kaum untersucht, rechtlich und finanziell leicht umsetzbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=137', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8281, 29, 16, 'BE', 'Ein Altenhilfestrukturgesetz soll soziale Infrastruktur für ältere Menschen bezirksübergreifend sichern und finanzieren.', '{2901}', null, 2, 2, null, 'Ein Gesetz mit gesicherter Finanzierung gibt Begegnungs- und Unterstützungsangeboten für Ältere Dauer und Verbindlichkeit. Wirkung kaum untersucht; Gesetzgebung und Aufbau brauchen mehrere Jahre.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=148', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8282, 29, 16, 'BE', 'Aufsuchende Nachbarschaftshilfe für allein lebende ältere Menschen soll ausgebaut werden.', '{2901}', 8144, 2, 3, null, 'Erreicht auch Menschen, die nicht von sich aus Treffpunkte aufsuchen. Besuchsangebote wirkten in Übersichten seltener als Gruppenangebote (60 % gegenüber 79 % der Studien mit Verbesserung). Gut umsetzbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=151', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8283, 29, 16, 'BE', 'Wohnortnahe soziale Treffpunkte und aufsuchende Stadtteilarbeit sollen erhalten und ausgebaut werden.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=243', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8284, 29, 16, 'BE', 'Ein zusätzlicher Fonds soll Personal und Infrastruktur im Breitensport stärken, dessen Vereine Schutzräume gegen soziale Isolation bieten.', '{2901}', 8145, 1, 3, null, 'Vereine und Engagement bieten Kontaktgelegenheiten, die Förderung wirkt aber nur indirekt und erreicht Verwitwete nicht gezielt. Wirkung auf Einsamkeit kaum untersucht; leicht umsetzbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=313', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8285, 29, 16, 'BE', 'Psychische Gesundheit soll im Unterricht und in Projektwochen thematisiert werden, um Wissen zu Erkrankungen und Hilfen zu vermitteln und Stigmatisierung abzubauen.', '{2903,2904}', 8151, 1, 3, null, 'Unterricht kann Wissen vermitteln, doch Übersichten finden wenig Beleg, dass schulische Präventionsprogramme Angst oder Depression senken; einzelne Ansätze zeigen Effekte. Land kann Lehrpläne anpassen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=137', 'https://europepmc.org/article/MED/31734106', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8286, 29, 16, 'BE', 'Bezirkliche Kriseninterventionszentren mit Chats und aufsuchenden Hilfen sowie der Berliner Krisendienst sollen gestärkt werden.', '{2903}', 8155, 2, 2, null, 'Krisenmodelle sind laut Cochrane-Übersicht gangbar und werden gut angenommen, die Studienlage ist aber klein und von geringer bis mäßiger Qualität. Flächendeckender Aufbau braucht Personal und Zeit.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=137', 'https://europepmc.org/article/MED/26633650', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8287, 29, 16, 'BE', 'Psychosoziale Kontakt- und Beratungsstellen mit Einzel- und Gruppenberatung sowie alltagsnaher Unterstützung sollen in jedem Bezirk bestehen.', '{2903}', 8154, 2, 3, null, 'Wohnortnahe, niedrigschwellige Beratung senkt Hürden bei der Hilfesuche und hilft beim Einordnen von Beschwerden. Wirkung einzelner Modelle kaum vergleichend untersucht; Land kann Förderung zügig ausweiten.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=137', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8288, 29, 16, 'BE', 'Die psychosoziale Unterstützung junger Menschen soll vernetzt und durch Lotsen, niedrigschwellige Krisenkontakte und Anlaufstellen erreichbar werden.', '{2903}', 8156, 2, 3, null, 'Anlaufstellen ohne Termin und Diagnose erleichtern jungen Menschen den ersten Schritt zur Hilfe. Wirkung kaum vergleichend untersucht; Länder und Kommunen können Standorte rasch fördern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=179', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8289, 29, 16, 'MV', 'Begegnungsorte und Nachbarschaftsnetzwerke gegen Einsamkeit im Alter unterstützen.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=12', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8290, 29, 16, 'MV', 'Resilienzförderung und Lerntrainings in schulischen Rahmenplänen verankern.', '{2903}', 8151, 1, 3, null, 'Unterricht kann Wissen vermitteln, doch Übersichten finden wenig Beleg, dass schulische Präventionsprogramme Angst oder Depression senken; einzelne Ansätze zeigen Effekte. Land kann Lehrpläne anpassen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=6', 'https://europepmc.org/article/MED/31734106', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8291, 29, 16, 'MV', 'Digitale Hilfsangebote und flächendeckende Schulpsychologie für Kinder und Jugendliche ausbauen.', '{2903}', 8150, 2, 2, null, 'Fachkräfte vor Ort erleichtern das Erkennen von Belastungen und die Hilfesuche; Angebot und Bedarf klaffen bislang auseinander. Wirkung kaum untersucht, Personalgewinnung dauert Jahre.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=11', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-06', false, true, 'blind'),
  (8292, 29, 16, 'MV', 'Gesundheitsförderndes Verhalten, Emotionsregulation und den Umgang mit Stress im Schulalltag verankern.', '{2903}', 8151, 1, 3, null, 'Unterricht kann Wissen vermitteln, doch Übersichten finden wenig Beleg, dass schulische Präventionsprogramme Angst oder Depression senken; einzelne Ansätze zeigen Effekte. Land kann Lehrpläne anpassen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=11', 'https://europepmc.org/article/MED/31734106', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8293, 29, 16, 'MV', 'Die psychosoziale Beratung durch Studierendenwerke dauerhaft sichern und erweitern.', '{2903}', 8154, 2, 3, null, 'Wohnortnahe, niedrigschwellige Beratung senkt Hürden bei der Hilfesuche und hilft beim Einordnen von Beschwerden. Wirkung einzelner Modelle kaum vergleichend untersucht; Land kann Förderung zügig ausweiten.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=17', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8294, 29, 16, 'ST', 'Barrierefreie Begegnungsstätten und offene Treffpunkte fördern und erweitern.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=58', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8295, 29, 16, 'ST', 'Nachbarschaftshilfe und Senior:innenassistenz mit Beratungsangeboten unterstützen.', '{2901}', 8144, 2, 3, null, 'Erreicht auch Menschen, die nicht von sich aus Treffpunkte aufsuchen. Besuchsangebote wirkten in Übersichten seltener als Gruppenangebote (60 % gegenüber 79 % der Studien mit Verbesserung). Gut umsetzbar.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=59', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8296, 29, 16, 'ST', 'Patenschaften für Alleinstehende fördern.', '{2901}', 8148, 1, 3, null, 'Persönliche Kontakte können Alleinstehende erreichen, die Reichweite kleiner Modellprojekte ist aber gering. Einzelangebote wirkten in Übersichten seltener als Gruppenangebote; leicht umsetzbar.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=59', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8297, 29, 16, 'ST', 'Präventions-, Beratungs- und Behandlungsangebote für Betroffene ausbauen und bestehende Angebote unterstützen.', '{2903}', 8154, 2, 3, null, 'Wohnortnahe, niedrigschwellige Beratung senkt Hürden bei der Hilfesuche und hilft beim Einordnen von Beschwerden. Wirkung einzelner Modelle kaum vergleichend untersucht; Land kann Förderung zügig ausweiten.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=52', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8298, 29, 16, 'ST', 'Medizinisches Fachpersonal durch Aufklärung für Stigmata sensibilisieren und diese abbauen.', '{2904}', 8153, 1, 3, null, 'Schulungen können Vorurteile im Umfeld von Betroffenen mindern; Studien zeigen vor allem kurzfristige Einstellungsänderungen, kaum Verhaltens- oder Langzeitwirkung. Leicht umsetzbar.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=52', 'https://europepmc.org/article/MED/26410341', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8299, 29, 16, 'ST', 'Psychisches Leiden infolge medizinischer Stigmata verhindern, behandeln und rechtlich ahnden.', '{2904}', null, 1, 2, null, 'Weniger Stigmatisierung durch Behandelnde kann die Hilfesuche erleichtern, erreicht aber nur einen Teil der Scham. Rechtliche Ahndung ist schwer zu fassen; Wirkung kaum untersucht.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=52', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8300, 29, 16, 'ST', 'Lotsenstellen in die psychische Versorgung und frühe Hilfen mit Familienhebammen landesweit stärken.', '{2903}', 8157, 1, 3, null, 'Lotsen helfen, vorhandene Angebote zu finden, schaffen aber keine zusätzlichen Behandlungsplätze. Wirkung auf Wartezeiten und Hilfesuche kaum untersucht; gut umsetzbar.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=60', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8301, 29, 17, null, 'Mindestrenten nach Versicherungsdauer sichern und stufenweise erhöhen', '{2902}', 8163, 2, 2, null, 'Hebt Alterseinkommen direkt an; Studien zu Geldleistungen und psychischer Gesundheit sind uneinheitlich, der Einfluss auf Einsamkeit ist kaum untersucht. Kosten erfordern Finanzierung und Vorlauf.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=22', null, 'gemischt', '2026-10-06', false, true, 'blind'),
  (8302, 29, 17, null, 'Wohnortnahe Freizeit- und Bildungsangebote für Kinder und Familien zugänglich machen', '{2902}', 8165, 1, 2, null, 'Freizeit- und Bildungsangebote ermöglichen Teilhabe unabhängig vom Einkommen, wirken aber nur mittelbar auf Einsamkeit. Zuständig sind Länder und Kommunen, der Bund kann nur mit Geld beitragen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=32', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8303, 29, 17, null, 'Ausbildungsplätze für Psychotherapeutinnen und -therapeuten schaffen', '{2905}', null, 1, 2, null, 'Mehr Ausbildungsplätze erhöhen langfristig die Zahl der Fachkräfte, ändern aber nicht die Kassensitze und wirken erst nach Jahren. Studienplätze sind Ländersache, der Bund kann nur beitragen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=27', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8304, 29, 17, 'BE', 'Stadtteilzentren ausbauen und dauerhaft sichern, Nachbarschafts- und Begegnungsprojekte fördern, gezielte Maßnahmen gegen Vereinsamung.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=12', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8305, 29, 17, 'BE', 'Schulpsychologinnen und Schulpsychologen flächendeckend an Schulen einsetzen.', '{2903}', 8150, 2, 2, null, 'Fachkräfte vor Ort erleichtern das Erkennen von Belastungen und die Hilfesuche; Angebot und Bedarf klaffen bislang auseinander. Wirkung kaum untersucht, Personalgewinnung dauert Jahre.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=16', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-06', false, true, 'blind'),
  (8306, 29, 17, 'MV', 'Sportvereine, Kulturangebote und Ehrenamt als Orte der Begegnung und sozialen Teilhabe stärken.', '{2901}', 8145, 1, 3, null, 'Vereine und Engagement bieten Kontaktgelegenheiten, die Förderung wirkt aber nur indirekt und erreicht Verwitwete nicht gezielt. Wirkung auf Einsamkeit kaum untersucht; leicht umsetzbar.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=15', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8307, 29, 17, 'MV', 'Soziale Orte und Unterstützungsstrukturen im ländlichen Raum fördern, mit Mobilitätsprogrammen und niedrigschwelligen Treffpunkten.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=15', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8308, 29, 17, 'MV', 'Die Landesstrategie gegen Einsamkeit mit konkreten Maßnahmen, klaren Zuständigkeiten und ausreichender Finanzierung ausbauen.', '{2901}', 8143, 1, 3, null, 'Strategie und Koordination schaffen selbst kein Angebot; die Wirkung hängt von den Maßnahmen ab, die daraus folgen. Wirkung solcher Strukturen kaum untersucht, rechtlich und finanziell leicht umsetzbar.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=15', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8309, 29, 17, 'MV', 'Krisentelefone und ambulante Hilfen für Menschen mit psychischen Erkrankungen und in akuten Belastungssituationen sichern und ausbauen.', '{2903}', 8155, 2, 2, null, 'Krisenmodelle sind laut Cochrane-Übersicht gangbar und werden gut angenommen, die Studienlage ist aber klein und von geringer bis mäßiger Qualität. Flächendeckender Aufbau braucht Personal und Zeit.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=15', 'https://europepmc.org/article/MED/26633650', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8310, 29, 17, 'MV', 'Jugendsozialarbeit verlässlich finanzieren und Präventionsangebote für Kinder und Jugendliche zur Stärkung sozialer und mentaler Gesundheit ausbauen.', '{2903}', 8156, 2, 3, null, 'Anlaufstellen ohne Termin und Diagnose erleichtern jungen Menschen den ersten Schritt zur Hilfe. Wirkung kaum vergleichend untersucht; Länder und Kommunen können Standorte rasch fördern.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=15', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8311, 29, 17, 'MV', 'Schulen mit multiprofessionellen Teams zur Prävention psychischer Probleme ausstatten.', '{2903}', 8150, 2, 2, null, 'Fachkräfte vor Ort erleichtern das Erkennen von Belastungen und die Hilfesuche; Angebot und Bedarf klaffen bislang auseinander. Wirkung kaum untersucht, Personalgewinnung dauert Jahre.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=46', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-06', false, true, 'blind'),
  (8312, 29, 17, 'MV', 'Mehr Schulpsychologen und dauerhaft finanzierte Schulsozialarbeit bereitstellen.', '{2903}', 8150, 2, 2, null, 'Fachkräfte vor Ort erleichtern das Erkennen von Belastungen und die Hilfesuche; Angebot und Bedarf klaffen bislang auseinander. Wirkung kaum untersucht, Personalgewinnung dauert Jahre.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=61', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-06', false, true, 'blind'),
  (8313, 29, 17, 'MV', 'Erziehungs- und Familienberatung mit kurzen Wartezeiten und niedrigschwelligen Zugängen stärken.', '{2903}', 8154, 2, 3, null, 'Wohnortnahe, niedrigschwellige Beratung senkt Hürden bei der Hilfesuche und hilft beim Einordnen von Beschwerden. Wirkung einzelner Modelle kaum vergleichend untersucht; Land kann Förderung zügig ausweiten.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=61', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8314, 29, 17, 'MV', 'Präventionsangebote zu psychischer Gesundheit, Resilienz, Medienkompetenz und Konfliktbewältigung ausbauen.', '{2903}', 8151, 1, 3, null, 'Unterricht kann Wissen vermitteln, doch Übersichten finden wenig Beleg, dass schulische Präventionsprogramme Angst oder Depression senken; einzelne Ansätze zeigen Effekte. Land kann Lehrpläne anpassen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=61', 'https://europepmc.org/article/MED/31734106', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8315, 29, 17, 'ST', 'Einen landesweiten Personalschlüssel für Schulsozialarbeit und Schulpsychologie einführen.', '{2903}', 8150, 2, 2, null, 'Fachkräfte vor Ort erleichtern das Erkennen von Belastungen und die Hilfesuche; Angebot und Bedarf klaffen bislang auseinander. Wirkung kaum untersucht, Personalgewinnung dauert Jahre.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=47', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-06', false, true, 'blind'),
  (8316, 29, 17, 'ST', 'Schulpsychologen präventiv einsetzen und für Lernende sowie Lehrkräfte niedrigschwellig erreichbar machen.', '{2903}', 8150, 2, 2, null, 'Fachkräfte vor Ort erleichtern das Erkennen von Belastungen und die Hilfesuche; Angebot und Bedarf klaffen bislang auseinander. Wirkung kaum untersucht, Personalgewinnung dauert Jahre.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=48', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-06', false, true, 'blind'),
  (8317, 29, 17, 'ST', 'Multiprofessionelle Teams mit Schulpsychologie als Regelangebot an Schulen etablieren.', '{2903}', 8150, 2, 2, null, 'Fachkräfte vor Ort erleichtern das Erkennen von Belastungen und die Hilfesuche; Angebot und Bedarf klaffen bislang auseinander. Wirkung kaum untersucht, Personalgewinnung dauert Jahre.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=48', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-06', false, true, 'blind'),
  (8318, 29, 17, 'ST', 'Den sozialpsychiatrischen Dienst ausbauen und stärker in Jugend-, Schul- und Integrationsarbeit einbinden.', '{2903}', 8158, 2, 3, null, 'Bestehende kommunale Dienste erreichen auch Menschen, die von sich aus keine Hilfe suchen. Wirkung der Ausbaustufen kaum untersucht; Land kann Mittel und Aufgaben zügig anpassen.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=59', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8586, 29, 18, null, 'Bedarfsplanung für Psychotherapie anpassen, mehr Kassensitze und gerechtere Verteilung', '{2905}', 8167, 2, 3, null, 'Mehr Kassensitze setzen direkt an der Kapazität an; Befragungen sehen fehlende Termine als Hauptengpass. Wirkung bisheriger Reformen nur teils belegt. Bund und Selbstverwaltung können es regeln.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=132', 'https://europepmc.org/articles/PMC13288593', 'offen', '2026-10-07', false, true, 'blind'),
  (8587, 29, 18, null, 'Flächendeckende Gesundheitskioske für individuelle, niedrigschwellige Beratung', '{2903}', null, 1, 2, null, 'Im Hamburger Modell gut angenommen und mit weniger vermeidbaren Klinikfällen, aber ohne messbare Verbesserung der Gesundheitskompetenz; Beratung ist allgemein, nicht auf psychische Gesundheit ausgerichtet. Flächendeckender Aufbau braucht Finanzierungseinigung mit Kassen und Kommunen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=130', 'https://www.uni-hamburg.de/newsroom/presse/2021/pm17.html', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8588, 29, 18, null, 'Resilienzförderung schon im Kita-Alter, Weiterbildung für Fach- und Lehrkräfte', '{2903}', 8585, 1, 2, null, 'Früh ansetzende Förderung und geschulte Fachkräfte können Belastungen eher erkennen; Übersichten finden aber wenig Beleg, dass Präventionsprogramme in Bildungseinrichtungen Angst oder Depression senken. Kita und Schule sind Ländersache, der Bund kann nur fördern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=132', 'https://europepmc.org/article/MED/31734106', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8618, 29, 18, 'BE', 'Mental Health Coaches an Schulen und Jugendzentren und Mental Health im Lehrplan verankern; Mental Health Days vor Ort einführen.', '{2903}', 8150, 2, 2, null, 'Fachkräfte vor Ort erleichtern das Erkennen von Belastungen und die Hilfesuche; Angebot und Bedarf klaffen bislang auseinander. Wirkung kaum untersucht, Personalgewinnung dauert Jahre.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=83', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-08', false, true, 'blind'),
  (8619, 29, 18, 'BE', 'Pflichtfach Lebenskompetenz mit Schwerpunkt psychische Gesundheit, Empathie und sozial-emotionalem Lernen, zunächst an Pilotschulen.', '{2903}', 8151, 1, 3, null, 'Unterricht kann Wissen vermitteln, doch Übersichten finden wenig Beleg, dass schulische Präventionsprogramme Angst oder Depression senken; einzelne Ansätze zeigen Effekte. Land kann Lehrpläne anpassen.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=48', 'https://europepmc.org/article/MED/31734106', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8620, 29, 18, 'BE', 'Gesundheitskioske und Gesundheitslots*innen für niedrigschwellige, mehrsprachige Beratung in benachteiligten Stadtteilen.', '{2903}', null, 1, 2, null, 'Mehrsprachige Gesundheitskioske wurden in einer Evaluation gut angenommen, Gesundheitskompetenz stieg aber nicht messbar; psychische Gesundheit ist nur ein Thema unter vielen. Dauerfinanzierung mit Kassen ungeklärt.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=80', 'https://www.aerzteblatt.de/archiv/223895', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8621, 29, 18, 'BE', 'Betroffene in Anti-Stigma-Kampagnen und Programme zur psychischen Gesundheit einbeziehen.', '{2904}', 8152, 1, 3, null, 'Aufklärung und Kontaktprogramme verbessern kurzfristig Einstellungen und Wissen; langfristige Effekte und Wirkung auf die Hilfesuche sind kaum belegt. Gut umsetzbar.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=83', 'https://europepmc.org/article/MED/26410341', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8622, 29, 18, 'BE', 'Begegnungsorte gegen Einsamkeit wie Mehrgenerationencafés und Nachbarschaftszentren schaffen.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=83', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8623, 29, 18, 'ST', 'Niedrigschwellige Angebote zur psychischen Gesundheit wie Mental-Health-Cafés, Gruppen und digitale Formate ausbauen.', '{2903}', 8154, 2, 3, null, 'Wohnortnahe, niedrigschwellige Beratung senkt Hürden bei der Hilfesuche und hilft beim Einordnen von Beschwerden. Wirkung einzelner Modelle kaum vergleichend untersucht; Land kann Förderung zügig ausweiten.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=39', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8624, 29, 18, 'ST', 'Männerberatungsstellen und psychosoziale Beratung ausbauen und regional besser verfügbar machen.', '{2904}', 8154, 2, 3, null, 'Wohnortnahe, niedrigschwellige Beratung senkt Hürden bei der Hilfesuche und hilft beim Einordnen von Beschwerden. Wirkung einzelner Modelle kaum vergleichend untersucht; Land kann Förderung zügig ausweiten.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=128', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8625, 29, 18, 'ST', 'Öffentlichkeitsarbeit, die das Holen von Hilfe als normale Stärke vermittelt.', '{2904}', 8152, 1, 3, null, 'Aufklärung und Kontaktprogramme verbessern kurzfristig Einstellungen und Wissen; langfristige Effekte und Wirkung auf die Hilfesuche sind kaum belegt. Gut umsetzbar.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=128', 'https://europepmc.org/article/MED/26410341', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8626, 29, 18, 'ST', 'Soziale Gesundheit stärken durch Programme gegen Einsamkeit und Förderung stabiler Beziehungen.', '{2901}', null, 1, 3, null, 'Gruppenangebote gegen Isolation zeigen in Übersichten häufig Verbesserungen, die Studien sind aber oft schwach; ohne benannte Programme bleibt offen, was entsteht. Land kann Programme leicht auflegen.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=40', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-08', false, true, 'blind');

